// 从右上角或者或者左下角类似于一棵二叉搜索树
//每次移动都缩小一排或者一列的搜索范围，时间复杂度为O(m+n)
func searchMatrix(matrix [][]int, target int) bool {
	if matrix == nil {
		return false
	}
	row := len(matrix) - 1
	col := 0
	for row >= 0 && col <= len(matrix[0])-1 {
		if matrix[row][col] == target {
			return true
		} else if matrix[row][col] < target {
			col++
		} else {
			row--
		}
	}
	return false
}

