func searchMatrix2(matrix [][]int, target int) bool {
	binSearch := func(arr []int) bool {
		l := 0
		r := len(arr) - 1
		for l <= r {
			mid := l + (r-l)/2
			if arr[mid] == target {
				return true
			} else if arr[mid] > target {
				r = mid - 1
			} else {
				l = mid + 1
			}
		}
		return false
	}
	for _, row := range matrix {
		if binSearch(row) {
			return true
		}
	}
	return false
}

